import * as fsPromises from "fs/promises";
import { promises as aliasedPromises } from "node:fs";
import * as nodeFs from "node:fs";
writeFile("one.json", "one");
fsPromises.rm("two.json");
aliasedPromises.rename("a", "b");
nodeFs.promises.mkdir("three");

aliasedMonkeyPatch:
import * as nodeFs from "node:fs";
import { promises as fsPromises } from "node:fs";
nodeFs.rmSync = namedReplacement;
fsPromises.writeFile = () => Promise.resolve();
nodeFs.prototype.writeFile = namedReplacement;
Object.defineProperty(nodeFs, "rmSync", { value: namedReplacement });
Object.defineProperties(fsPromises, { writeFile: { value: namedReplacement } });
Object.assign(nodeFs, { mkdirSync: namedReplacement });

